(function(){var root=document.querySelector('.fx-cnt');if(!root)return;function sp(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--speed'))||1}
function run(){root.querySelectorAll('[data-to]').forEach(function(el){var to=+el.dataset.to,t0=null,d=1600/sp();function f(t){if(!t0)t0=t;var p=Math.min((t-t0)/d,1),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e);if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)})}
if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){run();io.disconnect()}},{threshold:.3});io.observe(root)}else run();
root.addEventListener('click',run)})();
